package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.util.Set;

import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.RDF;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

/** Preserves the electrical-grid result regression through the replacement of the legacy sketch planner. */
class LmdbElectricalGridQueryTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final String GRID = "http://example.com/theme/grid/";
	private static final IRI SUBSTATION = VF.createIRI(GRID + "Substation");
	private static final IRI GENERATOR = VF.createIRI(GRID + "Generator");
	private static final IRI FEEDS = VF.createIRI(GRID + "feeds");
	private static final IRI NAME = VF.createIRI(GRID + "name");

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void optimizedElectricalGridQueryReturnsExpectedDistinctEntityCount(boolean estimatorEnabled,
			@TempDir File directory) {
		LmdbStore store = new LmdbStore(directory, new LmdbStoreConfig("spoc,ospc,psoc")
				.setSketchEstimatorEnabled(estimatorEnabled)
				.setSketchEstimatorMemoryBudgetBytes(4L * 1024L * 1024L));
		if (estimatorEnabled) {
			store.setExperimentalQueryOptimizations(true);
		}
		SailRepository repository = new SailRepository(store);
		repository.init();
		if (estimatorEnabled) {
			assertSketchFixtureProfile(store);
		}
		try {
			loadGrid(repository);
			if (estimatorEnabled) {
				assertTrue(store.forceFlushSketchEstimator());
			}
			try (SailRepositoryConnection connection = repository.getConnection()) {
				String plan = connection.prepareTupleQuery(query()).explain(Explanation.Level.Optimized).toString();
				assertTrue(plan.contains(FEEDS.stringValue()), plan);
				assertTrue(plan.contains(NAME.stringValue()), plan);
				try (TupleQueryResult rows = connection.prepareTupleQuery(query()).evaluate()) {
					assertTrue(rows.hasNext(), "the aggregate query must return one result row");
					BindingSet row = rows.next();
					assertEquals(Set.of("count"), row.getBindingNames());
					assertEquals(VF.createLiteral("33", XSD.INTEGER), row.getValue("count"),
							"three substations and thirty generators feed substations 1, 2, or 3");
					assertFalse(rows.hasNext(), "COUNT must return exactly one result row");
				}
			}
		} finally {
			repository.shutDown();
		}
	}

	private static void loadGrid(SailRepository repository) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin(IsolationLevels.NONE);
			for (int index = 0; index < 300; index++) {
				Resource substation = VF.createIRI("urn:test:substation:" + index);
				connection.add(substation, RDF.TYPE, SUBSTATION);
				connection.add(substation, NAME, VF.createLiteral("Substation " + index));
			}
			for (int index = 0; index < 120; index++) {
				Resource generator = VF.createIRI("urn:test:generator:" + index);
				connection.add(generator, RDF.TYPE, GENERATOR);
				connection.add(generator, FEEDS, VF.createIRI("urn:test:substation:" + index % 12));
			}
			for (int index = 0; index < 600; index++) {
				connection.add(VF.createIRI("urn:test:alias-holder:" + index), VF.createIRI(GRID + "alias"),
						VF.createLiteral("Substation " + (1 + index % 3)));
			}
			connection.commit();
		}
	}

	private static String query() {
		return """
				SELECT (COUNT(DISTINCT ?entity) AS ?count) WHERE {
				  {
				    VALUES ?target { "Substation 1" "Substation 2" }
				    ?entity a <http://example.com/theme/grid/Substation> .
				    ?entity <http://example.com/theme/grid/name> ?name .
				    FILTER ((?name = ?target) || (?name = "Substation 3"))
				  }
				  UNION
				  {
				    VALUES ?target { "Substation 1" "Substation 2" }
				    ?entity a <http://example.com/theme/grid/Generator> .
				    ?entity <http://example.com/theme/grid/feeds> ?substation .
				    ?substation <http://example.com/theme/grid/name> ?name .
				    FILTER ((?name = ?target) || (?name = "Substation 3"))
				  }
				  OPTIONAL { ?entity <http://example.com/theme/grid/feeds> ?substation2 . }
				}
				""";
	}

	private static void assertSketchFixtureProfile(LmdbStore store) {
		try {
			assertTrue(store.getQueryExecutionPolicy().experimentalQueryOptimizations());
			assertNotNull(store.getBackingStore().getSketchBasedJoinEstimator());
		} catch (AssertionError failure) {
			try {
				store.shutDown();
			} catch (RuntimeException | Error closeFailure) {
				failure.addSuppressed(closeFailure);
			}
			throw failure;
		}
	}
}
